<?php require __DIR__ . '/bootstrap.php';
header('Content-Type: text/plain; charset=utf-8');
$pdo = db(); $done = [];
$pdo->exec("ALTER TABLE leads ADD COLUMN IF NOT EXISTS notes TEXT NULL"); $done[]='leads.notes';
$pdo->exec("CREATE TABLE IF NOT EXISTS site_settings (k VARCHAR(60) NOT NULL PRIMARY KEY, v TEXT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"); $done[]='site_settings';
$pdo->exec("CREATE TABLE IF NOT EXISTS seo_settings (k VARCHAR(60) NOT NULL PRIMARY KEY, v TEXT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"); $done[]='seo_settings';
$pdo->exec("CREATE TABLE IF NOT EXISTS services (id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(190), title VARCHAR(200), category VARCHAR(120), price VARCHAR(80), image TEXT, short_desc TEXT, full_desc TEXT, features TEXT, benefits TEXT, meta_title VARCHAR(200), meta_desc VARCHAR(300), keywords TEXT, status VARCHAR(20) NOT NULL DEFAULT 'draft', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"); $done[]='services';
$pdo->exec("CREATE TABLE IF NOT EXISTS blog_posts (id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(190), title VARCHAR(200), category VARCHAR(120), author VARCHAR(120), image TEXT, read_time VARCHAR(40), publish_date DATE NULL, excerpt TEXT, content MEDIUMTEXT, meta_title VARCHAR(200), meta_desc VARCHAR(300), keywords TEXT, status VARCHAR(20) NOT NULL DEFAULT 'draft', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"); $done[]='blog_posts';
$pdo->exec("CREATE TABLE IF NOT EXISTS portfolio (id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(190), title VARCHAR(200), client VARCHAR(160), category VARCHAR(120), image TEXT, short_desc TEXT, full_desc TEXT, gallery TEXT, challenge TEXT, solution TEXT, results TEXT, testimonial TEXT, testimonial_author VARCHAR(160), testimonial_role VARCHAR(160), meta_title VARCHAR(200), meta_desc VARCHAR(300), keywords TEXT, status VARCHAR(20) NOT NULL DEFAULT 'draft', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"); $done[]='portfolio';
echo "OK · " . implode(', ', $done);
